using System.Text.Json;
using System.Xml;
using System.Xml.Linq;

namespace Legacy.Maliev.DataMigration.Console;

internal static class IsoDefinitionAssembler
{
    // Inputs must already be flat imported and held by the owner-protected parent custody.
    // No worker is launched and no TRX/result/native value is generated by this method.
    internal static IsoDefinitionProof Assemble(CurrentAppOwnedRepairCustody files, IsoDefinitionSubject intended,
        string trxPath, string heldTestAssemblyPath, string executedTestAssemblyPath, string ledgerDirectory,
        IsoDefinitionArtifact acceptedSource, IsoDefinitionArtifact acceptedOwners, IsoDefinitionArtifact sourceCatalog,
        FreshSchemaPlan fixtureSource, IReadOnlyList<CurrentOwnerIsoSourceObservation> fixtureOwners,
        DateTimeOffset began, DateTimeOffset completed, DateTimeOffset expires, string keyId, DateTimeOffset now)
    {
        using var xml = XmlReader.Create(new MemoryStream(files.Read(trxPath, maximumBytes: 8_000_000, sharedReader: true), false),
            new XmlReaderSettings { DtdProcessing = DtdProcessing.Prohibit, XmlResolver = null, MaxCharactersInDocument = 8_000_000 });
        var trx = XDocument.Load(xml); XNamespace ns = "http://microsoft.com/schemas/VisualStudio/TeamTest/2010";
        var cases = new List<IsoDefinitionCase>(); var runs = new List<IsoDefinitionRun>();
        foreach (var result in trx.Descendants(ns + "UnitTestResult"))
        {
            string stdout = (string?)result.Element(ns + "Output")?.Element(ns + "StdOut") ?? throw IsoDefinitionCases.Invalid();
            string[] markers = stdout.Split('\n').Select(x => x.Trim()).Where(x => x.StartsWith("ISO_DEFINITION_CASE=", StringComparison.Ordinal)).ToArray();
            if (markers.Length != 1) { throw IsoDefinitionCases.Invalid(); }
            string id = markers[0][20..];
            if (!IsoDefinitionCases.Required.Contains(id, StringComparer.Ordinal)) { throw IsoDefinitionCases.Invalid(); }
            IsoDefinitionArtifact Slot(string phase)
            {
                return Artifact(Path.Combine(ledgerDirectory, id + "-" + phase + ".json"));
            }

            var entry = MigrationConsole.DecodeOwnerIso<IsoDefinitionEntry>(files.Read(Slot("entered").Path, sharedReader: true));
            var projections = new List<IsoDefinitionArtifact>();
            var rejectedSnapshots = new List<IsoDefinitionArtifact>();
            bool negative = id.StartsWith("unsupported-", StringComparison.Ordinal) || id.StartsWith("candidate-", StringComparison.Ordinal);
            if (negative) { rejectedSnapshots.Add(Slot("before-rejection")); rejectedSnapshots.Add(Slot("after-rejection")); }
            if (id == "width")
            {
                foreach (string database in new[] { "iso_country_fixture", "iso_material_fixture" })
                { foreach (string phase in new[] { "before", "candidate", "rollback", "commit-candidate", "readback" }) { projections.Add(Slot(database + "-" + phase)); } }
            }
            IsoDefinitionNativePhases? native = id.StartsWith("literal-", StringComparison.Ordinal)
                ? new(Slot("before"), Slot("transactional-after"), Slot("rolled-back"), Slot("commit-candidate"), Slot("independent-readback")) : null;
            cases.Add(new(id, (string?)result.Attribute("testName") ?? throw IsoDefinitionCases.Invalid(),
                (string?)result.Attribute("testId") ?? throw IsoDefinitionCases.Invalid(),
                (string?)result.Attribute("executionId") ?? throw IsoDefinitionCases.Invalid(), entry.RunId,
                executedTestAssemblyPath, Artifact(heldTestAssemblyPath) with { SourcePath = executedTestAssemblyPath }, Slot("entered"), Slot("exited"), native, projections,
                negative ? Slot("rejected") : null, rejectedSnapshots));
            if (entry.RunId is { } run)
            {
                using var metadata = JsonDocument.Parse(files.Read(Slot("resource-container").Path, maximumBytes: 8_000_000, sharedReader: true));
                JsonElement actual = metadata.RootElement;
                var port = actual.GetProperty("NetworkSettings").GetProperty("Ports").GetProperty("5432/tcp").EnumerateArray().Single();
                runs.Add(new(run, actual.GetProperty("Id").GetString() ?? throw IsoDefinitionCases.Invalid(),
                    actual.GetProperty("Name").GetString()!.TrimStart('/'),
                    int.Parse(port.GetProperty("HostPort").GetString()!, System.Globalization.CultureInfo.InvariantCulture),
                    Slot("resource-attempt"), Slot("resource-container"), Slot("resource-capacity"), Slot("resource-disposed"), Slot("resource-absence")));
            }
        }
        var proof = new IsoDefinitionProof("current-owner-iso-definition-precursor-v1", intended,
            acceptedSource, acceptedOwners, sourceCatalog, fixtureSource, fixtureOwners, began, completed, expires,
            Artifact(trxPath), cases, runs, keyId, null);
        IsoDefinitionPrecursor.RequireBody(files, proof, intended, now);
        return proof;
        IsoDefinitionArtifact Artifact(string path)
        { byte[] bytes = files.Read(path, maximumBytes: 8_000_000, sharedReader: true); return new(path, CurrentAppOwnedRepairPermit.Hash(bytes)); }
    }
    internal static IsoDefinitionArtifact ImportActualArtifact(CurrentAppOwnedRepairCustody sourceFiles,
        string sourcePath, string destinationDirectory)
    {
        // Caller must acquire destination custody after the copy; no overwrite or rename of evidence.
        byte[] bytes = sourceFiles.Read(sourcePath, maximumBytes: 8_000_000, sharedReader: true);
        string destination = Path.Combine(destinationDirectory, Path.GetFileName(sourcePath));
        if (!Path.IsPathFullyQualified(destinationDirectory) || !Directory.Exists(destinationDirectory)) { throw IsoDefinitionCases.Invalid(); }
        using var output = new FileStream(destination, FileMode.CreateNew, FileAccess.Write, FileShare.Read);
        output.Write(bytes); output.Flush(flushToDisk: true); sourceFiles.Require();
        return new(destination, CurrentAppOwnedRepairPermit.Hash(bytes), sourcePath);
    }
}
